  ui_story_30330503_62_dialog_content = "Cambiemos de tema, joven Celestita.",
  ui_story_30330503_63_dialog_content = "Bien entonces. ¿Qué planeas hacer a continuación?",
  ui_story_30330503_64_dialog_content = "Completar mi misión como siempre.",
  ui_story_30330503_65_dialog_content = "Mi misión actual es regresar a Illumina para completar el informe sobre este incidente.",
  ui_story_30330503_66_dialog_content = "Si se me pide brindar apoyo en alguna batalla, entraré al campo de batalla con mis soldados.",
  ui_story_30330503_67_dialog_content = "¿Hmm? ¿Tienes que hacer todo eso tú misma?",
  ui_story_30330503_68_dialog_content = "Sí, así es más eficiente.",
