  ui_story_30330503_97_dialog_content = "<color=#e8d9bb>Después de sacudir su capa, Hiiro se va sin mirar atrás.</color>",
  ui_story_30330503_98_dialog_content = "<color=#e8d9bb>La observo mientras su esbelta silueta desaparece al doblar la esquina.</color>",
  ui_story_30330503_99_dialog_content = "<color=#e8d9bb>Sólo cuando recuerdo su rostro me doy cuenta de una cosa que fue constante en ella durante toda la conversación...</color>",
  ui_story_30330503_100_dialog_content = "<color=#e8d9bb>Su rostro sin expresión.</color>",
  ui_story_30020601_1_dialog_content = "Muy bien, mi patrullaje diario casi termina. Sólo necesito revisar el Puente...",
  ui_story_30020601_2_dialog_content = "El puente está todo despejado... ¿Mmm?",
  ui_story_30020601_3_dialog_content = "Oh, es Hiiro.",
  ui_story_30020601_4_dialog_content = "Parece estar ausente...",
  ui_story_30020601_5_dialog_content = "No creo haberla visto nunca así... Debería asegurarme de que está bien.",
  ui_story_30020601_6_dialog_content = "Hiiro, ¿Está todo bien? ¿Por qué estás mirando al vacío...",
