  ui_story_30020601_9_dialog_content = "Todavía sin respuesta.",
  ui_story_30020601_10_dialog_content = "<size=45>HIIRO! ESTÁS BIEN, HIIRO?!</size>",
  ui_story_30020601_11_dialog_content = "...Hmm?",
  ui_story_30020601_12_dialog_content = "Oh, es tú.",
  ui_story_30020601_13_dialog_content = "¿Qué pasa?",
