  ui_story_30020601_17_dialog_content = "Oh, ¿esto?",
  ui_story_30020601_18_dialog_content = "Soy yo.",
  ui_story_30020601_19_dialog_content = "¿Has estado mirando una foto tuya?",
  ui_story_30020601_20_dialog_content = "(Me pregunto qué tipo de foto puede hacer que se pierda así...)",
  ui_story_30020601_21_dialog_content = "(Tengo muchas ganas de verla...)",
  ui_story_30020601_22_dialog_content = "Realmente estás estirando el cuello ahí. ¿No te duele?",
  ui_story_30020601_23_dialog_content = "S-Sí, un poco.",
  ui_story_30020601_24_dialog_content = "Aquí.",
