  ui_story_30020601_27_dialog_content = "Mmm.",
  ui_story_30020601_28_dialog_content = "Pero... ¿Por qué te quedaste tan distraída mirando esta foto?",
  ui_story_30020601_29_dialog_content = "...",
  ui_story_30020601_30_dialog_content = "(Vaya, dejó de hablar otra vez...)",
  ui_story_30020601_31_dialog_content = "Está bien, entiendo si no quieres hablar de ello...",
  ui_story_30020601_32_dialog_content = "Puedo, si quieres saberlo.",
  ui_story_30020601_33_dialog_content = "Esto es de mis días de <color=#FFB400>entrenamiento</color> en las fuerzas defensivas de Illumina.",
  ui_story_30020601_34_dialog_content = "Como futuros graduados de la Academia Militar Illumina, hemos organizado para ustedes su primer entrenamiento de campo.",
