  ui_story_30020601_39_dialog_content = "Por esa razón...",
  ui_story_30020601_40_dialog_content = "¡Esto no será diferente de una operación militar real! ¡Tendrán que formar dos grupos de tres para llevar a cabo su misión!",
  ui_story_30020601_41_dialog_content = "¡Si encuentran algo más allá de sus capacidades, avisen inmediatamente a sus superiores! ¡Tal y como se les ha enseñado!",
  ui_story_30020601_42_dialog_content = "Hiiro, contamos contigo para velar de cerca por la seguridad de todos.",
  ui_story_30020601_43_dialog_content = "Lo haré.",
  ui_story_30020601_44_dialog_content = "Ah... ¡El olor a libertad!",
  ui_story_30020601_45_dialog_content = "¡Que vengan los Eclipsites, no tengo miedo! ¡Masacraré todo lo que se cruce en nuestro camino!",
  ui_story_30020601_46_dialog_content = "Nuestro entrenamiento de campo es demasiado fácil... ¿Qué tipo de peligro podríamos encontrar en nuestra línea defensiva? Qué chiste...",
  ui_story_30020601_47_dialog_content = "Es obvio que nadie quería hacer este tipo de trabajo de centinela servil, así que lo echaron a los estudiantes de la academia.",
  ui_story_30020601_48_dialog_content = "¡Sí, tienes razón! Es una pérdida total de tiempo y energía...",
  ui_story_30020601_49_dialog_content = "Qué pasa, Hiiro ¿El gran? ¿No hay palabras de oro de sabiduría? ¿O las quejas de la gente común como nosotros te ofendieron tanto que te dejaron sin palabras?",
  ui_story_30020601_50_dialog_content = "No.",
  ui_story_30020601_51_dialog_content = "Eso es extraño...",
  ui_story_30020601_52_dialog_content = "Pero viendo que nuestro entrenamiento es tan simple, apuesto...",
  ui_story_30020601_53_dialog_content = "El gran Hiiro ni siquiera necesita compañeros de equipo para completar esta misión. Puedes hacerlo todo tú solo, ¿no?",
  ui_story_30020601_54_dialog_content = "Servicio de centinela, limpieza de calles, comprobación de mensajes de advertencia... Cosas triviales como éstas...",
  ui_story_30020601_55_dialog_content = "Debería ser un paseo por el parque para los grandes y poderosos. Hiiro, que ya ha visto el combate y obtuvo la victoria para Illumina!",
  ui_story_30020601_56_dialog_content = "¿Entonces?",
  ui_story_30020601_57_dialog_content = "Entonces, si el perfecto Hiiro iba a terminar el trabajo sola...",
  ui_story_30020601_58_dialog_content = "¡Podría ganarse aún más elogios y gloria para ella cuando volvamos a la academia!",
  ui_story_30020601_59_dialog_content = "Además, una noble poderosa como tú nunca nos consideraría camaradas, ¿verdad?",
  ui_story_30020601_60_dialog_content = "La favorita del Gran Mariscal, que medita y se entrena incluso cuando no está de servicio...",
  ui_story_30020601_61_dialog_content = "¿Por qué alguien como tú se uniría a una gentuza común como nosotros?",
  ui_story_30020601_62_dialog_content = "... Así que así es como te sientes.",
  ui_story_30020601_63_dialog_content = "Entonces no importa.",
  ui_story_30020601_64_dialog_content = "¡¿Y qué se supone que significa eso?!",
  ui_story_30020601_65_dialog_content = "Significa que iré a patrullar una de las dos rutas y completaré mis deberes por mí misma.",
  ui_story_30020601_66_dialog_content = "El resto de ustedes puede tomar la otra ruta.",
  ui_story_30020601_67_dialog_content = "Hagan su elección y salgan primero.",
  ui_story_30020601_68_dialog_content = "¡Tú!",
  ui_story_30020601_69_dialog_content = "En ese caso, la mejor de las suertes en tu misión. Hiiro ¡El gran! ¡Intenta no morir ahí fuera!",
  ui_story_30020601_70_dialog_content = "¡Vamos, todos, vamos por aquí! ¡Buen viaje, Su Alteza!",
  ui_story_30020601_71_dialog_content = "Adiós, y tengan cuidado.",
  ui_story_30020601_72_dialog_content = "Humph, no es más que una pretenciosa aspirante y una acaparadora de gloria...",
  ui_story_30020601_73_dialog_content = "Escuché que es muy cercana con el <color=#FFB400>Gran Mariscal</color>... No creo que debas ser tan directo.",
  ui_story_30020601_74_dialog_content = "¡No me digas que te asusta una aduladora como ella!",
  ui_story_30020601_75_dialog_content = "Nos dieron motocicletas para el trabajo de centinela, ¿eh? No es mala elección...",
  ui_story_30020601_76_dialog_content = "Hay tres puntos de control a lo largo de esta ruta... Comencemos.",
  ui_story_30020601_77_dialog_content = "Punto de control A, todo despejado. Los sistemas de alerta son normales, y no hay señales de actividades del Eclipsite.",
  ui_story_30020601_78_dialog_content = "Punto de control B... ¡Allí!",
  ui_story_30020601_79_dialog_content = "Sólo un puñado de Eclipsites... No es una amenaza inmediata.",
  ui_story_30020601_80_dialog_content = "Punto de control B, despejado. La ruta es segura y los sistemas de alerta son normales.",
  ui_story_30020601_81_dialog_content = "Punto de control C, todo despejado. La ruta es segura, y el error en el sistema de alerta se ha resuelto.",
  ui_story_30020601_82_dialog_content = "Misión completa, vuelvo a la base.",
  ui_story_30020601_83_dialog_content = "Extraño...",
  ui_story_30020601_84_dialog_content = "Soy la única en el punto de encuentro...",
  ui_story_30020601_85_dialog_content = "La ruta que eligieron sólo tiene dos puntos de control. En circunstancias normales, deberían haber regresado antes que yo.",
  ui_story_30020601_86_dialog_content = "¿Podrían haberse encontrado con Eclipsites...?",
  ui_story_30020601_87_dialog_content = "Algo no está bien. ¡Debo ir a verlos!",
  ui_story_30020601_88_dialog_content = "¡Maldita sea! ¡¿Por qué hay tantos Eclipsites?!",
  ui_story_30020601_89_dialog_content = "¡Argh! Estoy herido...",
  ui_story_30020601_90_dialog_content = "¡Por aquí! ¡Todavía queda uno!",
  ui_story_30020601_91_dialog_content = "Siguen llegando... ¡Mantengan la línea, todos!",
  ui_story_30020601_92_dialog_content = "Los Eclipsites... ¡Van por ustedes allí! ¡Cuidado!",
  ui_story_30020601_93_dialog_content = "Bastardos... Cómo te atreves...",
  ui_story_30020601_94_dialog_content = "Rayos... Mi vendaje se desprendió... No puedo parar la hemorragia...",
  ui_story_30020601_95_dialog_content = "Pero aún así...",
  ui_story_30020601_96_dialog_content = "Pase lo que pase... No puedo morir en un lugar así... ¡No lo haré!",
  ui_story_30020601_97_dialog_content = "¡Esplendor Illumina! ¡¡Ahora muere!!",
  ui_story_30020601_98_dialog_content = "¡Sabía que algo iba mal!",
  ui_story_30020601_99_dialog_content = "¡Cálmate! ¡Ayúdame a atacar el flanco derecho! ¡Necesitamos crear un hueco!",
  ui_story_30020601_100_dialog_content = "Es eso... Hiiro? ¡Es! Es Hiiro!",
  ui_story_30020601_101_dialog_content = "¡¡¡Ayúdanos!!!",
  ui_story_30020601_102_dialog_content = "¡Graaagh!",
  ui_story_30020601_103_dialog_content = "¡Aquí vienen!",
  ui_story_30020601_104_dialog_content = "¡Toma los que están cerca! ¡Déjame el resto a mí!",
  ui_story_30020601_105_dialog_content = "Y así de fácil, le dimos la vuelta al asunto.",
  ui_story_30020601_106_dialog_content = "¿Es eso...?",
  ui_story_30020601_107_dialog_content = "¡Ey! ¡Cuidado con tu flanco!",
  ui_story_30020601_108_dialog_content = "¡Lo se!",
  ui_story_30020601_109_dialog_content = "¡¿Medio muerto y todavía tratando de acercarte a mí, eh?!",
  ui_story_30020601_110_dialog_content = "Fiu... Por fin se acabó...",
  ui_story_30020601_111_dialog_content = "Te debemos la vida, Hiiro!",
  ui_story_30020601_112_dialog_content = "Menos mal que has venido...",
  ui_story_30020601_113_dialog_content = "Tú... Me has salvado hace un momento, ¿verdad?",
  ui_story_30020601_114_dialog_content = "No dejes que se te suba a la cabeza... ¡Todavía puedo abrir camino para salir de aquí sin ti!",
  ui_story_30020601_115_dialog_content = "Bien... Parece que todavía puedes moverte.",
  ui_story_30020601_116_dialog_content = "Hiiro... Tu moto...",
  ui_story_30020601_117_dialog_content = "Creo que lo arruinaste cuando llegaste a la carga hace un momento...",
  ui_story_30020601_118_dialog_content = "Lo se. No es nada.",
  ui_story_30020601_119_dialog_content = "¿Aún puedes caminar?",
  ui_story_30020601_120_dialog_content = "¡Sí!",
  ui_story_30020601_121_dialog_content = "Bien. Los que aún puedan caminar, ayuden a llevar a los heridos de vuelta a la base.",
  ui_story_30020601_122_dialog_content = "¡Ey! Estoy hablando contigo, Hiiro! ¡Lo menos que puedes hacer es mirarme!",
  ui_story_30020601_123_dialog_content = "Nunca te pedí que me rescataras, ¿me oyes? ¡Lo hacía muy bien por mi cuenta!",
  ui_story_30020601_124_dialog_content = "Has completado la misión de nuestro equipo tú sola... Y también salvaste a todos...",
  ui_story_30020601_125_dialog_content = "¿No es suficiente para llevarlo e informar a los superiores?",
  ui_story_30020601_126_dialog_content = "¡¿Por qué rescatarme a mí también?!",
  ui_story_30020601_127_dialog_content = "No por ninguna razón en particular.",
  ui_story_30020601_128_dialog_content = "Todos moriremos algún día, pero hoy no era ese día para ti.",
  ui_story_30020601_129_dialog_content = "¡Tú!",
  ui_story_30020601_130_dialog_content = "<color=#e8d9bb>No mucho después...</color>",
  ui_story_30020601_131_dialog_content = "gran general Hiiro, Comandante de la 3ra Legión de la Federación Illumina!",
  ui_story_30020601_132_dialog_content = "¿Cómo debo referirme a usted ahora? supongo que lo de siempre Hiiro The Great seguirá funcionando, ¿o tienes una sugerencia mejor?",
  ui_story_30020601_133_dialog_content = "Di lo que piensas.",
  ui_story_30020601_134_dialog_content = "¿Sabes que alguien te denunció justo antes de tu ascenso?",
  ui_story_30020601_135_dialog_content = "Dicen que no entiendes cómo trabajar en equipo, que vas y vienes a tu antojo... que eres fría y distante...",
  ui_story_30020601_136_dialog_content = "No se equivocaron, por lo que veo.",
  ui_story_30020601_137_dialog_content = "¿Entonces?",
  ui_story_30020601_138_dialog_content = "¿\"Entonces\"? ¡¿Es todo lo que tienes que decir?!",
  ui_story_30020601_139_dialog_content = "Tsk... Sé que tú y el Gran Mariscal son cercanos.",
  ui_story_30020601_140_dialog_content = "Tan cercanos, de hecho, que no te importa si tu nombre queda <color=#FFB400>calumniado</color>. ¿Es así?",
  ui_story_30020601_141_dialog_content = "¿Consideras esto una calumnia?",
  ui_story_30020601_142_dialog_content = "Bien... ¡No hay duda que algo de eso es cierto!",
  ui_story_30020601_143_dialog_content = "Pero aun así, presenté pruebas para refutar sus falsas afirmaciones.",
  ui_story_30020601_144_dialog_content = "Mucha gente se presentó a testificar en tu defensa, también.",
  ui_story_30020601_145_dialog_content = "Y... Me las arreglé para arreglar tu moto rota.",
  ui_story_30020601_146_dialog_content = "¡Para reunir pruebas, claro!",
  ui_story_30020601_147_dialog_content = "Mmm.",
  ui_story_30020601_148_dialog_content = "¡¿\"Mmm\"...?! ¡¿Qué clase de respuesta es esa?!",
  ui_story_30020601_149_dialog_content = "¡¿Es todo lo que tienes que decir a alguien que acaba de salvar toda tu carrera?!",
  ui_story_30020601_150_dialog_content = "¡¿O estás tratando de decirme que no te importa si te ayudo o no?!",
  ui_story_30020601_151_dialog_content = "Mmm.",
  ui_story_30020601_152_dialog_content = "¡¡¡T-Tú...!!!",
  ui_story_30020601_153_dialog_content = "Gracias por presentar pruebas a mi favor.",
  ui_story_30020601_154_dialog_content = "Incluso si hay algo de verdad en las acusaciones...",
  ui_story_30020601_155_dialog_content = "No lo hacía por ti... ¡Lo hice porque soy una buena persona!",
  ui_story_30020601_156_dialog_content = "No sabía que tenías una historia tan apasionante, Hiiro...",
  ui_story_30020601_157_dialog_content = "¿\"Emocionante\"?",
  ui_story_30020601_158_dialog_content = "¡Sí! No tenía idea de que supieras manejar una motocicleta...",
  ui_story_30020601_159_dialog_content = "Ahora que lo pienso, nunca te he visto montar en una... ni llevar ese uniforme en esta foto.",
  ui_story_30020601_160_dialog_content = "No tenía ninguna razón para llevarlo nunca más después de graduarme en la academia. Parece que ahora tienen un nuevo diseño para el uniforme de los estudiantes.",
  ui_story_30020601_161_dialog_content = "En cuanto a la motocicleta, la devolví al equipo de patrulla después de repararla. Puede que todavía esté en uso.",
  ui_story_30020601_162_dialog_content = "Ya veo... y tu compañero de clase...",
  ui_story_30020601_163_dialog_content = "Aunque su actitud dejaba mucho que desear, parecía una persona que entendía las cosas.",
  ui_story_30020601_164_dialog_content = "¿Dónde está ella ahora? ¿Se unió a la 3ª Legión después de la graduación, como tú?",
  ui_story_30020601_165_dialog_content = "... No lo sé.",
  ui_story_30020601_166_dialog_content = "¿N-No sabes...?",
  ui_story_30020601_167_dialog_content = "No volvimos a vernos después de ese incidente.",
  ui_story_30020601_168_dialog_content = "Tampoco he oído nada sobre su trabajo o carrera.",
  ui_story_30020601_169_dialog_content = "No que haya razón para averiguarlo.",
  ui_story_30020601_170_dialog_content = "Si las opiniones y posiciones de cada uno cambian con el tiempo, pero siguen preocupándose por nuestra supuesta amistad del pasado...",
  ui_story_30020601_171_dialog_content = "Sólo hará que los asuntos actuales se compliquen innecesariamente.",
  ui_story_30020601_172_dialog_content = "Haber pasado algunos de nuestros días de juventud juntas ya es algo bueno. Bastante bien, de todos modos.",
  ui_story_30020601_173_dialog_content = "(A pesar de Hiiro suena tranquilo e indiferente...)",
  ui_story_30020601_174_dialog_content = "(Casi nunca habla de nada en profundidad...)",
  ui_story_30020601_175_dialog_content = "(¿Será... que ella también siente un poco de nostalgia por esos días?)",
  ui_story_30020601_176_dialog_content = "(De lo contrario, no se habría desconectado así por mirar una foto, ¿no?)",
  ui_story_30020601_177_dialog_content = "(Creo que ya sé qué hacer...)",
  ui_story_30020601_178_dialog_content = "May Veo esa foto de nuevo?",
  ui_story_30020601_179_dialog_content = "Seguro.",
  ui_story_30020601_180_dialog_content = "(Una boina militar, una capa negra, algunas insignias y un par de botas militares. Todos con rastros de sudor y lágrimas de incontables batallas del pasado...)",
  ui_story_30020601_181_dialog_content = "¿Tienes algo en mente? Miras la foto con mucha intensidad...",
  ui_story_30020601_182_dialog_content = "¡No, no es nada! Creo que te ves tan imponente en ese uniforme...",
  ui_story_30020601_183_dialog_content = "Ya lo dijiste.",
  ui_story_30020601_184_dialog_content = "Si no hay nada más, me voy.",
  ui_story_30020601_185_dialog_content = "Adiós.",
  ui_story_30020601_186_dialog_content = "<color=#e8d9bb>Diez días después</color>",
  ui_story_30020601_187_dialog_content = "Por fin está hecho...",
  ui_story_30020601_188_dialog_content = "Esto fue mucho más difícil de lo que esperaba...",
  ui_story_30020601_189_dialog_content = "Cierto... ¡Hagámoslo! ¡Sólo tengo que dárselo!",
  ui_story_30020601_190_dialog_content = "<color=#e8d9bb>Toc Toc Toc...</color>",
  ui_story_30020601_191_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30020601_192_dialog_content = "¿Mmm? Es Hiiro ¿No está en su habitación?",
  ui_story_30020601_193_dialog_content = "Debe tener importantes asuntos militares que atender... Realmente esperaba darle esto en persona...",
  ui_story_30020601_194_dialog_content = "Supongo que debería dejarlo en su puerta y ponerle una nota. \"Un regalo para...”",
  ui_story_30020601_195_dialog_content = "\"... Hiiro.\"",
  ui_story_30020601_196_dialog_content = "Es la 34ª vez que corto mal la tela hoy...",
  ui_story_30020601_197_dialog_content = "Y el material de las botas... Yo también lo arruiné...",
  ui_story_30020601_198_dialog_content = "¡¡Aaargh!!",
  ui_story_30020601_199_dialog_content = "Donación Hiiro el mismo uniforme que el de la foto parecía una idea tan simple...",
  ui_story_30020601_200_dialog_content = "Entonces, ¡¿por qué es tan difícil de hacer?!",
  ui_story_30020601_201_dialog_content = "Me pregunto si hay una mejor forma de hacerlo...",
  ui_story_30020601_202_dialog_content = "<color=#e8d9bb>El Gemio de Explorador Nublar</color>",
  ui_story_30020601_203_dialog_content = "Un cliente valioso ha llegado...",
  ui_story_30020601_204_dialog_content = "May Te pregunto ¿qué buscas hoy?",
  ui_story_30020601_205_dialog_content = "Hola, Lady Sheol. Me preguntaba... ¿si tienes este conjunto en stock?",
  ui_story_30020601_206_dialog_content = "¿Oh? Un uniforme de entrenamiento de la Academia Militar de Illumina al viejo estilo...",
  ui_story_30020601_207_dialog_content = "¡Así es! ¿Podría comprar uno aquí?",
  ui_story_30020601_208_dialog_content = "La capacidad del Gremio de Explorador Nublar para satisfacer las necesidades de nuestros clientes depende totalmente del precio que estén dispuestos a pagar...",
  ui_story_30020601_209_dialog_content = "E-Es... 10,000 Nightium... ¿suficiente...?",
  ui_story_30020601_210_dialog_content = "¿Oh?",
  ui_story_30020601_211_dialog_content = "¡Es todo lo que tengo a mi nombre!",
  ui_story_30020601_212_dialog_content = "Qué cliente tan magnánimo eres... Sí, esta suma es más que satisfactoria, si lo digo yo.",
  ui_story_30020601_213_dialog_content = "E-es así... <size=30>Hubiera ofrecido menos de haberlo sabido...</size>",
  ui_story_30020601_214_dialog_content = "Me pregunto si Hiiro...",
  ui_story_30020601_215_dialog_content = "¿Le gustará este regalo?",
  ui_story_30020601_216_dialog_content = "<color=#e8d9bb>Tres días después, en algún lugar cerca de la línea defensiva de Illumina...</color>",
  ui_story_30020601_217_dialog_content = "¡Ya terminé mi informe, Navegador! ¡Gracias por acompañarnos!",
  ui_story_30020601_218_dialog_content = "Oh sí, escuché al Comandante Hiiro se supone que debe estar por aquí hoy!",
  ui_story_30020601_219_dialog_content = "Jejeje... Todo el mundo dice que ha estado actuando completamente diferente últimamente...",
  ui_story_30020601_220_dialog_content = "¿Quieres ir a ver qué hace el comandante legendario? Hiiro ¿es hasta?",
  ui_story_30020601_221_dialog_content = "¡Estoy seguro de que no me hará responsable de nada si estás allí conmigo!",
  ui_story_30020601_222_dialog_content = "El comandante legendario Hiiro... ¿Así es como la están llamando ahora...?",
  ui_story_30020601_223_dialog_content = "Claro, vamos a saludar.",
  ui_story_30020601_224_dialog_content = "(No he sabido nada de ella estos últimos días. Me dará la oportunidad de preguntarle si recibió mi regalo, también...)",
  ui_story_30020601_225_dialog_content = "Hiiro...!",
  ui_story_30020601_226_dialog_content = "Oh, es tú.",
  ui_story_30020601_227_dialog_content = "Tu traje...",
  ui_story_30020601_228_dialog_content = "Mmm. Así es.",
  ui_story_30020601_229_option_content = "Temía que no lo entendieras.",
  ui_story_30020601_230_dialog_content = "Mis disculpas. He estado tan ocupada últimamente que olvidé darte las gracias.",
  ui_story_30020601_231_dialog_content = "¡Ah, e-está bien! Eres una Comandante, después de todo...",
  ui_story_30020601_232_option_content = "¡Te queda muy bien!",
  ui_story_30020601_233_dialog_content = "Creo que ese uniforme realmente te queda bien, Hiiro!",
  ui_story_30020601_234_dialog_content = "Gracias, PlayerName.",
  ui_story_30020601_235_dialog_content = "D-De nada...",
  ui_story_30020601_236_dialog_content = "Pero realmente, le queda perfecto, señorita. Hiiro!",
  ui_story_30020601_237_dialog_content = "No tengo la costumbre de dar las gracias dos veces...",
  ui_story_30020601_238_dialog_content = "Pero debo expresarle mi gratitud una vez más, porque...",
  ui_story_30020601_239_dialog_content = "Además de tu regalo, también me ayudaste a darme cuenta de algo...",
  ui_story_30020601_240_dialog_content = "...Que debería preocuparme más por mis compañeros y ver cómo están más a menudo.",
  ui_story_30020601_241_dialog_content = "Después de que me dieras este uniforme, le pregunté a alguien por mi compañera de clase a ver cómo estaba.",
  ui_story_30020601_242_dialog_content = "Pensé que alguien ambicioso como ella se quedaría en el ejército y ascendería de rango...",
  ui_story_30020601_243_dialog_content = "Pero, para mi sorpresa, se dedicó a la logística y se convirtió en transportista, trasladando mercancías entre las Subciudades.",
  ui_story_30020601_244_dialog_content = "¿Una transportadora?",
  ui_story_30020601_245_dialog_content = "Si. Específicamente, los que operan Kaas, el famoso vehículo de carga de Illumina.",
  ui_story_30020601_246_dialog_content = "He oído que es una gran conductora.",
  ui_story_30020601_247_dialog_content = "¿Te convertiste en comandante de la legión, mientras que tu compañera se convirtió en repartidora?",
  ui_story_30020601_248_dialog_content = "Por qué siento que, con una personalidad así...",
  ui_story_30020601_249_dialog_content = "Estas equivocado.",
  ui_story_30020601_250_dialog_content = "Está perfectamente satisfecha con su trabajo y su estatus.",
  ui_story_30020601_251_dialog_content = "\"No me importa lo que haga o dónde lo haga, siempre que sirva a Illumina.\" Esas fueron las palabras de mi compañera de clase.",
  ui_story_30020601_252_dialog_content = "Dice que también recuerda esos días con nostalgia...",
  ui_story_30020601_253_dialog_content = "Por supuesto, su \"rescate desinteresado\" de la Comandante de la 3ª Legión sigue siendo su mejor recuerdo...",
  ui_story_30020601_254_dialog_content = "Eso definitivamente suena a ella.",
  ui_story_30020601_255_dialog_content = "Su sincera confesión me hizo ver que yo también echaba de menos el tiempo que pasamos juntas en la academia.",
  ui_story_30020601_256_dialog_content = "Las dos llevábamos este uniforme y luchábamos una al lado de la otra.",
  ui_story_30020601_257_dialog_content = "Y a pesar de nuestras diferencias, nos ayudábamos y protegíamos mutuamente.",
  ui_story_30020601_258_dialog_content = "Puede que ahora no trabajemos en el mismo sitio, pero sin darnos cuenta, siempre hemos estado trabajando por el mismo objetivo.",
  ui_story_30020601_259_dialog_content = "La verdad es que éramos un equipo.",
  ui_story_30020601_260_dialog_content = "Como están trabajando por el mismo objetivo, ustedes estarán siempre en el mismo equipo.",
  ui_story_30020601_261_dialog_content = "¿Perdón?",
  ui_story_30020601_262_dialog_content = "¡N-No, así no! Yo, eh... Olvídalo.",
  ui_story_30020601_263_dialog_content = "En cualquier caso, tiene razón.",
  ui_story_30020601_264_dialog_content = "Solo como...",
  ui_story_30020601_265_dialog_content = "Como una vez luchamos lado a lado, ¿verdad?",
  ui_story_30020601_266_dialog_content = "Nunca olvidaré el ataque que expulsó a Tabaad.",
  ui_story_30020601_267_dialog_content = "Escuchar eso es más que suficiente.",
  ui_story_30020601_268_dialog_content = "Hemos recorrido un largo camino, ¿verdad?",
  ui_story_30020601_269_dialog_content = "Por cierto, se llama Lucy. Supongo que debía decírtelo.",
  ui_story_30020601_270_dialog_content = "Lucy... Una soldado ordinaria de Illumina.",
  ui_story_30020602_1_dialog_content = "\"Saludos.\"",
  ui_story_30020602_2_dialog_content = "\"Los vientos se vuelven secos y fríos con el cambio de las estaciones. Rezo por tu bienestar, así como por el bienestar de tus amigos.\"",
  ui_story_30020602_3_dialog_content = "\"Montaña Nube ha estado tranquila desde tu partida. No han aparecido Eclipsites dentro de la barrera desde entonces.\"",
  ui_story_30020602_4_dialog_content = "\"Sin embargo, notamos un movimiento inusual en el sello que mantiene la barrera en su lugar.\"",
  ui_story_30020602_5_dialog_content = "\"El movimiento anormal se detuvo tan rápido como comenzó, y no tuvo ningún efecto visible en la barrera.\"",
  ui_story_30020602_6_dialog_content = "\"Por esta razón, dudaba en informarte sobre esto. Sin embargo, Sanki insiste en pedirte que regreses y realices una investigación adecuada—\"",
  ui_story_30020602_7_dialog_content = "¿Eh? ¿Fue Sanki? Parece que se ha vuelto mucho más maduro ahora.",
  ui_story_30020602_8_dialog_content = "La luz de la luna reflejada por la espada, brilla fría y clara.",
  ui_story_30020602_9_dialog_content = "El deseo de Sanki de proteger Montaña Nube no es diferente. Aunque a veces puede ser dominante, su corazón e intenciones son puros.",
  ui_story_30020602_10_dialog_content = "No voy a defraudarlo.",
  ui_story_30020602_11_dialog_content = "... Entonces, ¿eso significa que vas a Montaña Nube para investigar la barrera?",
  ui_story_30020602_12_dialog_content = "Sí.",
  ui_story_30020602_13_dialog_content = "R-¿Aquí y ahora mismo?",
  ui_story_30020602_14_dialog_content = "Correcto.",
  ui_story_30020602_15_dialog_content = "¿Incluso después de que el Gran Mariscal te dejó con cinco pilas de trabajo de fin de año por hacer?!",
  ui_story_30020602_16_dialog_content = "He terminado esos trabajos.",
  ui_story_30020602_17_dialog_content = "<size=45>¿¡¿Todo?!?</size>",
  ui_story_30020602_18_dialog_content = "¿Qué eres, una máquina? La mayoría de las personas tendrían que trabajar hasta la noche durante un mes solo para hacer todo eso. ¡Ningún cuerpo podría manejar ese tipo de estrés!",
  ui_story_30020602_19_dialog_content = "La carta de Granny me ha dado mucho de qué preocuparme. Sin siquiera darme cuenta, terminé todo mi trabajo.",
  ui_story_30020602_20_dialog_content = "No creo que eso sea algo que puedas hacer \"sin siquiera darte cuenta\"...",
  ui_story_30020602_21_dialog_content = "PlayerName... ¿También has estado ocupado últimamente?",
  ui_story_30020602_22_dialog_content = "No realmente, no. Ninguno de mi trabajo es urgente en este momento... ¿Por qué?",
  ui_story_30020602_23_dialog_content = "¡Oh, ya sé por qué! ¿Quieres que te lleve a la Isla de las Nubes, verdad? No es un problema; ¡sólo déjamelo a mí!",
  ui_story_30020602_24_dialog_content = "...",
  ui_story_30020602_25_dialog_content = "Uh, ¿me equivoqué?",
  ui_story_30020602_26_dialog_content = "... No, adivinaste correctamente.",
  ui_story_30020602_27_dialog_content = "Simplemente no estoy acostumbrado a este sentimiento... de que alguien sepa lo que quiero antes de que pueda siquiera preguntar.",
  ui_story_30020602_28_dialog_content = "Se siente como si estuviera aprovechándome de ti.",
  ui_story_30020602_29_dialog_content = "¡Jajaja, para nada! Siempre te ocupas de mí, así que esto es lo menos que podría hacer por ti!",
  ui_story_30020602_30_dialog_content = "Tienes mi agradecimiento. Para ser honesto, no podré hacer mucho sin tu ayuda.",
  ui_story_30020602_31_dialog_content = "No puedo entrar en la barrera de la Montaña Nube. Para evitar cualquier error, necesito la ayuda de alguien que pueda sentir el perímetro de la barrera.",
  ui_story_30020602_32_dialog_content = "Y considerando la velocidad y eficacia, nadie es mejor para la tarea que tú.",
  ui_story_30020602_33_dialog_content = "PlayerName, ¿vendrás conmigo y me prestarás tu apoyo?",
  ui_story_30020602_34_dialog_content = "(Ella pidió mi ayuda correctamente después de todo. Supongo que la cortesía de Hiiro es algo que nunca desaparecerá...)",
  ui_story_30020602_35_dialog_content = "¡Solo déjamelo a mí! ¡El Caelestite siempre hace el trabajo!",
  ui_story_30020602_36_dialog_content = "...",
  ui_story_30020602_37_dialog_content = "Ejem... Lo siento por eso. He estado trabajando en un nuevo lema últimamente, y lo grito cada vez que consigo un nuevo trabajo.",
  ui_story_30020602_38_dialog_content = "No volverá a suceder, lo prometo.",
  ui_story_30020602_39_dialog_content = "Ahh, la Isla de las Nubes es tan pacífica y tranquila como siempre.",
  ui_story_30020602_40_dialog_content = "Pido disculpas por la espera, PlayerName.",
  ui_story_30020602_41_dialog_content = "¡Wow! T-Tú te ves increíble con este vestido...",
  ui_story_30020602_42_dialog_content = "... Estas son las ropas tradicionales de la Familia Sakura. Granny me las dio antes de que partimos la última vez.",
  ui_story_30020602_43_dialog_content = "Durante muchos años, ella ha trabajado incansablemente para proteger la barrera.",
  ui_story_30020602_44_dialog_content = "Como descendiente de la Familia Sakura, sentí que debía ofrecer mi más sincera gratitud, por eso me cambié a este atuendo.",
  ui_story_30020602_45_dialog_content = "Aunque no parece que me quede muy bien—",
  ui_story_30020602_46_dialog_content = "¡Te queda perfecto!",
  ui_story_30020602_47_dialog_content = "¡El personaje heroico y el brillante cabello rosa son la combinación perfecta para estas hermosas ropas!",
  ui_story_30020602_48_dialog_content = "De hecho, con la forma en que resaltan tu personalidad elegante y reservada, ¡diría que fueron hechos solo para ti!",
  ui_story_30020602_49_dialog_content = "Realmente no sé cómo ponerlo en palabras... ¡Pero estoy igualmente asombrado!",
  ui_story_30020602_50_dialog_content = "PlayerName...",
  ui_story_30020602_51_dialog_content = "Jejeje, para alguien que no sabe qué decir, seguro que tienes habilidad con las palabras, jovencito.",
  ui_story_30020602_52_dialog_content = "¡G-Granny?! ¡Deberías haber dicho algo cuando llegaste!",
  ui_story_30020602_53_dialog_content = "Tenía la intención de darte la bienvenida, pero...",
  ui_story_30020602_54_dialog_content = "Cuando los vi a los dos parados allí, no tuve el corazón para molestarlos.",
  ui_story_30020602_55_dialog_content = "¡Granny...!",
  ui_story_30020602_56_dialog_content = "Aparte de investigar la barrera, también quería visitarte.",
  ui_story_30020602_57_dialog_content = "Así que por favor no te consideres una molestia de ningún tipo.",
  ui_story_30020602_58_dialog_content = "Jeje, es bueno ser educado y compuesto, Hiiro, pero no deberías estar tan tenso todo el tiempo.",
  ui_story_30020602_59_dialog_content = "Después de todo, te veías muy adorable cuando estabas hablando con PlayerName justo ahora.",
  ui_story_30020602_60_dialog_content = "...",
  ui_story_30020602_61_dialog_content = "(Uh-oh, Hiiro no es bueno en este tipo de situaciones...)",
  ui_story_30020602_62_dialog_content = "Qué bueno verte de nuevo, PlayerName. Has crecido en altura, ¿no es así?",
  ui_story_30020602_63_dialog_content = "¡Vaya, parece que también te has vuelto más guapo!",
  ui_story_30020602_64_dialog_content = "Muy bien, muy bien. Me llena el corazón de alegría verlos a ambos.",
  ui_story_30020602_65_dialog_content = "Oh, Granny, me estás avergonzando... Jajaja...",
  ui_story_30020602_66_dialog_content = "Estaba observándote a ambos desde la distancia, y me recordaste mucho a los padres de Hiiro hace todos esos años.",
  ui_story_30020602_67_dialog_content = "El tiempo nos roba tanto, pero también nos trae cosas nuevas y maravillosas, como las jóvenes parejas...",
  ui_story_30020602_68_dialog_content = "\"¿Parejas jóvenes\"? D-Definitivamente tienes una idea equivocada aquí, Granny...",
  ui_story_30020602_69_dialog_content = "(Estoy totalmente perdido. ¿Qué está pasando aquí? ¿Por qué siento como si estuviera conociendo a la familia de alguien por primera vez?!)",
  ui_story_30020602_70_dialog_content = "D-Dime, Granny, no veo a Sanki por aquí... ¿?",
  ui_story_30020602_71_dialog_content = "Oh, no contengas la respiración. Él no quiere que Hiiro lo vea hasta que esté listo para impresionarla.",
  ui_story_30020602_72_dialog_content = "Me alegra que él esté motivado.",
  ui_story_30020602_73_dialog_content = "(¡Oh bien, ella recuperó la compostura!)",
  ui_story_30020602_74_dialog_content = "Cuéntanos sobre la barrera, Granny. ¿Has consultado a la sacerdotisa en la isla principal al respecto?",
  ui_story_30020602_75_dialog_content = "Sí, lo he hecho. Al principio pensé que los movimientos estaban conectados con la isla principal, pero la sacerdotisa afirma que se originaron en algún lugar aún más lejano.",
  ui_story_30020602_76_dialog_content = "Es muy probable que la tribu del dios de la montaña esté llamando desde el este.",
  ui_story_30020602_77_dialog_content = "... ¿La tribu del dios de la montaña?",
  ui_story_30020602_78_dialog_content = "¿Así que esos movimientos fueron la respuesta del dios de la montaña a su gente? Qué misterioso...",
  ui_story_30020602_79_dialog_content = "¿Y la barrera sigue sin verse afectada?",
  ui_story_30020602_80_dialog_content = "Parecería que sí, al menos por ahora. Por eso no quería interrumpir tu trabajo...",
  ui_story_30020602_81_dialog_content = "Como dije, por favor no te consideres una molestia de ningún tipo. La Isla de las Nubes también es mi hogar.",
  ui_story_30020602_82_dialog_content = "Incluso si es solo una precaución, me gustaría investigar a fondo el área.",
  ui_story_30020602_83_dialog_content = "Me alegra escucharlo, Hiiro. Gracias por venir desde tan lejos por nosotros.",
  ui_story_30020602_84_dialog_content = "Gracias a PlayerName, no fue ningún problema en absoluto.",
  ui_story_30020602_85_dialog_content = "Si acaso, todos deberíamos agradecerte por mantener la barrera durante tantos años...",
  ui_story_30020602_86_dialog_content = "En nombre de las Familias Sakura y Sakae, me gustaría expresar nuestra más profunda gratitud y respeto.",
  ui_story_30020602_87_dialog_content = "Oh, no hay necesidad de eso. Hago esto porque quiero hacerlo. Es justo como dijiste...",
  ui_story_30020602_88_dialog_content = "\"También la Isla de las Nubes es mi hogar.\"",
  ui_story_30020602_89_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_30020602_90_dialog_content = "<color=#e8d9bb>¡Golpe! Bofetada, bofetada!</color>",
  ui_story_30020602_91_dialog_content = "Graah—",
  ui_story_30020602_92_dialog_content = "Ese debería ser el último de ellos.",
  ui_story_30020602_93_dialog_content = "¡Gracias a Dios...!",
  ui_story_30020602_94_dialog_content = "La barrera parece estar aguantando muy bien en cada ubicación.",
  ui_story_30020602_95_dialog_content = "Los pocos Eclipsites que deambulan por aquí tampoco se atreven a pasar por él. Supongo que los movimientos del sello no afectaron la fuerza de la barrera.",
  ui_story_30020602_96_dialog_content = "Eso es un alivio, ¿verdad?",
  ui_story_30020602_97_dialog_content = "Sí. Podemos irnos sabiendo que la Isla de las Nubes es perfectamente segura por ahora.",
  ui_story_30020602_98_dialog_content = "...",
  ui_story_30020602_99_dialog_content = "(Hiiro está mirando fijamente a las montañas... ¿Está nostálgica?)",
  ui_story_30020602_100_dialog_content = "¿Por qué no vamos a ver la Montaña Nube en la isla cercana? Recuerdo que la vista de la montaña era especialmente hermosa cuando se miraba desde lejos.",
  ui_story_30020602_101_dialog_content = "¡...!",
  ui_story_30020602_102_dialog_content = "Tu capacidad para empatizar con los demás es casi aterradora.",
  ui_story_30020602_103_dialog_content = "No estabas usando tus poderes en mí justo ahora, ¿verdad?",
  ui_story_30020602_104_dialog_content = "¡No! ¡Absolutamente no!",
  ui_story_30020602_105_dialog_content = "... Solo quiero verte feliz, eso es todo. Usar mis poderes solo tendría el efecto contrario.",
  ui_story_30020602_106_dialog_content = "Relájate. Solo estaba bromeando.",
  ui_story_30020602_107_dialog_content = "Oh... Solo era una broma... Jajaja...",
  ui_story_30020602_108_dialog_content = "Espera...",
  ui_story_30020602_109_dialog_content = "<size=45>Tú eres el que da miedo, Hiiro!</size>",
  ui_story_30020602_110_dialog_content = "¡Wow, el clima de hoy hace que Cloud Mountain se vea aún más impresionante!",
  ui_story_30020602_111_dialog_content = ".... Sí.",
  ui_story_30020602_112_dialog_content = "Entonces ahí es donde duerme el dios de la montaña, ¿eh? Espero que la tribu oriental pueda conocerlo algún día.",
  ui_story_30020602_113_dialog_content = "Mmm.",
  ui_story_30020602_114_dialog_content = "Sanki está tan obsesionado con perseguirte. Me pregunto si ha estado ayudando a Granny a recoger leña...",
  ui_story_30020602_115_dialog_content = "Mmm.",
  ui_story_30020602_116_dialog_content = "... ¿Qué pasa, Hiiro? Has estado tan callado todo este tiempo.",
  ui_story_30020602_117_dialog_content = "...",
  ui_story_30020602_118_dialog_content = "Aunque mi casa está justo frente a mí, aún parece tan lejana. No puedo evitar sentirme algo sola.",
  ui_story_30020602_119_dialog_content = "Pero cuando lo miro contigo, esa soledad se tiñe de calidez.",
  ui_story_30020602_120_dialog_content = "No puedo imaginar lo frío que sería sentarse aquí solo.",
  ui_story_30020602_121_dialog_content = "Tampoco tienes que preocuparte por eso. Ese día nunca llegará.",
  ui_story_30020602_122_dialog_content = "¡Porque siempre estaré allí para llevarte de vuelta a la Isla de las Nubes con mi Coloso!",
  ui_story_30020602_123_dialog_content = "El Celestita siempre consigue el—Eh, no importa.",
  ui_story_30020602_124_dialog_content = "...",
  ui_story_30020602_125_dialog_content = "Je.",
  ui_story_30020602_126_dialog_content = "Acabas de sonreír...",
  ui_story_30020602_127_dialog_content = "(¿Eh? Hay algo cerca...)",
  ui_story_30020602_128_option_content = "Escaneo psíquico",
  ui_story_30020602_129_dialog_content = "Oh, no... Hiiro! Siento Eclipsites en ese estanque!",
  ui_story_30020602_130_dialog_content = "<anim type=Shake>Grahhh—!!</anim>",
  ui_story_30020602_131_dialog_content = "... ¡Déjame ir! Argh—Glub, glub, glub...",
  ui_story_30020602_132_dialog_content = "¡PlayerName!",
  ui_story_30020602_133_dialog_content = "Tú monstruos sucios...",
  ui_story_30020602_134_dialog_content = "¡Dispérsate y trasciende-!",
  ui_story_30020602_135_dialog_content = "Graah...",
  ui_story_30020602_136_dialog_content = "<color=#e8d9bb>Con una velocidad relámpago, Hiiro saca su espada y convierte a los atacantes en polvo, sin dejar rastro de su existencia.</color>",
  ui_story_30020602_137_dialog_content = "<color=#e8d9bb>Su atuendo elegante hace que su presencia impresionante sea aún más pintoresca.</color>",
  ui_story_30020602_138_dialog_content = "<color=#e8d9bb>Sin embargo, ella no tiene intención de preservar la belleza de este momento por mucho tiempo.</color>",
  ui_story_30020602_139_dialog_content = "¡PlayerName! ¿Estás bien? ¡Toma mi mano, rápido!",
  ui_story_30020602_140_dialog_content = "Glub, glub, glub... H-Hiiro...",
  ui_story_30020602_141_option_content = "Toma la mano de Hiiro",
  ui_story_30020602_142_dialog_content = "<anim type=Shake>Grahhh—!!</anim>",
  ui_story_30020602_143_option_content = "Escaneo psíquico",
  ui_story_30020602_144_dialog_content = "Hiiro... Eclipsites... detrás de ti! Glub, glub, glub...",
  ui_story_30020602_145_dialog_content = "¡Argh!",
  ui_story_30020602_146_dialog_content = "<color=#e8d9bb>¡Golpe! Bofetada, bofetada!</color>",
  ui_story_30020602_147_dialog_content = "Graah...",
  ui_story_30020602_148_dialog_content = "Glub, glub, glub...",
  ui_story_30020602_149_dialog_content = "¡PlayerName! ¡PlayerName!",
  ui_story_30020602_150_dialog_content = "¡No te preocupes, ya voy!",
  ui_story_30020602_151_dialog_content = "Ah... ¡Achu!",
  ui_story_30020602_152_dialog_content = "No esperaba que me arrastraran al agua... Pensé que esta vez estaba perdido de seguro.",
  ui_story_30020602_153_dialog_content = "Menos mal que eres tan poderoso. Gracias a ti, solo tragué unos cuantos tragos de agua de estanque y eso es todo, jaja...",
  ui_story_30020602_154_dialog_content = "¿Te estás riendo?",
  ui_story_30020602_155_dialog_content = "¡Lo-lo siento—!",
  ui_story_30020602_156_dialog_content = "Realmente te retrasé esta vez...",
  ui_story_30020602_157_dialog_content = "Eso no es lo que me molesta... Solo olvídalo.",
  ui_story_30020602_158_dialog_content = "Estás empapado. A este ritmo, pronto te resfriarás.",
  ui_story_30020602_159_dialog_content = "Pero tú también.",
  ui_story_30020602_160_dialog_content = "Deberíamos encender un fuego y secarnos. ¡Voy a recoger un poco de leña!",
  ui_story_30020602_161_dialog_content = "...",
  ui_story_30020602_162_dialog_content = "...",
  ui_story_30020602_163_dialog_content = "...",
  ui_story_30020602_164_dialog_content = "...",
  ui_story_30020602_165_dialog_content = "...",
  ui_story_30020602_166_dialog_content = "¡Lo siento mucho por hoy!",
  ui_story_30020602_167_dialog_content = "Si tan solo hubiera sido un poco más cuidadoso, tú tampoco te habrías mojado—",
  ui_story_30020602_168_dialog_content = "Es cierto que deberías reflexionar sobre tus errores.",
  ui_story_30020602_169_dialog_content = "¡Lo soy! ¡Lo prometo!",
  ui_story_30020602_170_dialog_content = "No importa quién seas; en la batalla, la primera prioridad de todos debería ser su propia seguridad.",
  ui_story_30020602_171_dialog_content = "Si algo te hubiera pasado hoy—",
  ui_story_30020602_172_dialog_content = "... Ni siquiera quiero pensar en ello.",
  ui_story_30020602_173_dialog_content = "Hiiro...",
  ui_story_30020602_174_dialog_content = "Hace mucho tiempo que me acostumbré a proteger a los demás, pero tú eres la primera persona—",
  ui_story_30020602_175_dialog_content = "...",
  ui_story_30020602_176_dialog_content = "¿E-El primer persona?",
  ui_story_30020602_177_dialog_content = "(¿La primera persona que es demasiado estúpida para proteger?)",
  ui_story_30020602_178_dialog_content = "¡La primera persona que intentó protegerme en su lugar...!",
  ui_story_30020602_179_dialog_content = "¡Los Eclipsites estaban más cerca de ti, y aún así me advertiste en lugar de cubrirte! ¿¡Qué diablos estabas pensando?!",
  ui_story_30020602_180_dialog_content = "Realmente no estaba pensando... No me mires así. ¡Fue solo instinto!",
  ui_story_30020602_181_dialog_content = "¿Instinto?",
  ui_story_30020602_182_dialog_content = "... Como dije, tu amabilidad puede ser aterradora a veces.",
  ui_story_30020602_183_dialog_content = "Nadie quiere imaginar un futuro sin ti en él.",
  ui_story_30020602_184_dialog_content = "Para que las cosas florezcan y luego se marchiten es el orden natural del mundo.",
  ui_story_30020602_185_dialog_content = "Y aún así, perderte haría que ese orden pareciera aún más cruel...",
  ui_story_30020602_186_dialog_content = "Hiiro... Lo siento. No tenía idea de que estuvieras tan preocupado por mí.",
  ui_story_30020602_187_dialog_content = "Pero debí saberlo.",
  ui_story_30020602_188_dialog_content = "Cuando primero sentí a esos Eclipsites, inmediatamente pensé en ti. Es normal que tú también estés igual de preocupado por mi seguridad.",
  ui_story_30020602_189_dialog_content = "Fui demasiado imprudente esta vez.",
  ui_story_30020602_190_dialog_content = "...",
  ui_story_30020602_191_dialog_content = "Mientras entiendas.",
  ui_story_30020602_192_dialog_content = "¿Crees que la tribu del este también está preocupada por el dios de la montaña en este momento?",
  ui_story_30020602_193_dialog_content = "No puedo hablar por los dioses, pero siempre hay personas que se preocupan por ti, tanto en el pasado como en el presente.",
  ui_story_30020602_194_dialog_content = "Tus padres, tu maestro, Granny, Sanki...",
  ui_story_30020602_195_dialog_content = "Y yo.",
  ui_story_30020602_196_dialog_content = "... May ¿Puedo preguntarte algo?",
  ui_story_30020602_197_dialog_content = "Claro, ¿qué es?",
  ui_story_30020602_198_dialog_content = "<size=30>¿Sentiste lo mismo por mí como Granny más temprano hoy? ¿P-Pensaste que yo era... adorable?</size>",
  ui_story_30020602_199_dialog_content = "... ¿Qué fue eso? No te escuché claramente.",
  ui_story_30020602_200_dialog_content = "No es nada. Olvídalo.",
  ui_story_30020602_201_dialog_content = "...",
  ui_story_30020602_202_dialog_content = "Sí, eras adorable.",
  ui_story_30020602_203_dialog_content = "—!",
  ui_story_30020602_204_dialog_content = "Extremadamente, de hecho.",
  ui_story_30020602_205_dialog_content = "<color=#e8d9bb>La luz tranquila de la hoguera proyecta un color extraño en el rostro de Hiiro.</color>",
  ui_story_30020602_206_dialog_content = "<color=#e8d9bb>Quizás sea el color de las flores de cerezo que florecieron temprano en un lugar lejano, o el color de las emociones poderosas que esta hermosa dama es demasiado tímida para expresar.</color>"
}
return config
